import { sourceName, loadPackages, formatValue, withSource } from "./site.js"

source = sourceName()
pkgName = new URLSearchParams(window.location.search).get("pkg")
metricsInfo = FileAttachment("data/metrics.json").json()
pkgs = loadPackages(source)

// PACKAGES may hold more than one record per package; show all of them.
matches = pkgs.filter((p) =&gt; p.Package === pkgName)












































{
  document.title = `${pkgName ?? "Package"} – val.repo (POC)`;
  const back = htl.html`&lt;p&gt;&lt;a href=${withSource("index.html", source)}&gt;← All packages&lt;/a&gt;&lt;/p&gt;`;
  if (!matches.length) {
    return htl.html`${back}&lt;h1&gt;Package not found&lt;/h1&gt;
      &lt;p&gt;No package &lt;code&gt;${pkgName ?? ""}&lt;/code&gt; in ${source === "prod" ? "production PACKAGES" : "the fixture"}.&lt;/p&gt;`;
  }
  return htl.html`${back}${matches.map(report)}`;
}







function report(p) {
  const { metrics, ...fields } = p;
  return htl.html`
    &lt;h1&gt;${p.Package} &lt;small class="text-muted"&gt;${p.Version}&lt;/small&gt;&lt;/h1&gt;
    &lt;h2&gt;Description&lt;/h2&gt;
    &lt;table class="table table-sm desc-table"&gt;&lt;tbody&gt;
      ${Object.entries(fields).map(([k, v]) =&gt; htl.html`&lt;tr&gt;&lt;td&gt;${k}&lt;/td&gt;&lt;td&gt;${v}&lt;/td&gt;&lt;/tr&gt;`)}
    &lt;/tbody&gt;&lt;/table&gt;
    &lt;h2&gt;Metrics&lt;/h2&gt;
    ${metricSections(metrics)}
    &lt;h2&gt;Reproduce&lt;/h2&gt;
    &lt;p&gt;Full run logs are not published. To recompute these metrics locally with
    &lt;a href="https://github.com/pharmaR/val.meter"&gt;val.meter&lt;/a&gt;:&lt;/p&gt;
    &lt;pre&gt;&lt;code&gt;${reproduceCode(p.Package)}&lt;/code&gt;&lt;/pre&gt;`;
}

// Group metrics by their first tag; values missing from PACKAGES are flagged.
function metricSections(metrics) {
  const known = new Set(metricsInfo.map((m) =&gt; m.name));
  const groups = d3.group(metricsInfo, (m) =&gt; m.tags[0] ?? "other");
  const other = groups.get("other");
  if (other) groups.delete("other"), groups.set("other", other);
  const unknown = Object.keys(metrics).filter((n) =&gt; !known.has(n));
  if (unknown.length) groups.set("no metadata", unknown.map((name) =&gt; ({ name, title: name, tags: [], permissions: [] })));
  return [...groups].map(([tag, ms]) =&gt; htl.html`
    &lt;h3&gt;${tag[0].toUpperCase() + tag.slice(1)}&lt;/h3&gt;
    &lt;table class="table table-sm"&gt;&lt;thead&gt;&lt;tr&gt;&lt;th&gt;Metric&lt;/th&gt;&lt;th&gt;Value&lt;/th&gt;&lt;th&gt;Requires&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;&lt;tbody&gt;
      ${ms.map((m) =&gt; htl.html`&lt;tr&gt;
        &lt;td&gt;&lt;strong&gt;${rawHTML(m.title)}&lt;/strong&gt;
          &lt;div class="metric-desc"&gt;${rawHTML(m.description ?? "")}&lt;/div&gt;&lt;/td&gt;
        &lt;td&gt;${m.name in metrics ? formatValue(metrics[m.name]) : htl.html`&lt;em class="text-muted"&gt;not available&lt;/em&gt;`}&lt;/td&gt;
        &lt;td&gt;${m.permissions.map((x) =&gt; htl.html`&lt;span class="perm"&gt;${x}&lt;/span&gt; `)}&lt;/td&gt;
      &lt;/tr&gt;`)}
    &lt;/tbody&gt;&lt;/table&gt;`);
}

// metrics.json holds HTML converted from val.meter's Rd docs at build time.
function rawHTML(s) {
  const span = document.createElement("span");
  span.innerHTML = s;
  return span;
}

function reproduceCode(name) {
  const perms = [...new Set(metricsInfo.flatMap((m) =&gt; m.permissions))];
  const permArg = perms.length ? `, permissions = permissions(${perms.map((x) =&gt; JSON.stringify(x)).join(", ")})` : "";
  return `# pak::pak("pharmaR/val.meter")
library(val.meter)
p &lt;- pkg(${JSON.stringify(name)}${permArg})
metrics(p)`;
}

import { sourceName, loadPackages, formatValue, packageHref, withSource } from "./site.js"

source = sourceName()
metricsInfo = FileAttachment("data/metrics.json").json()

loaded = {
  const t0 = performance.now();
  const pkgs = await loadPackages(source);
  return { pkgs, seconds: (performance.now() - t0) / 1000 };
}
pkgs = loaded.pkgs

// Only show metric columns that occur in this PACKAGES file.
metricCols = metricsInfo.map((m) =&gt; m.name).filter((n) =&gt; pkgs.some((p) =&gt; n in p.metrics))

rows = pkgs.map((p) =&gt; ({ Package: p.Package, Version: p.Version, License: p.License, ...p.metrics }))



















































sourceLabels = ({
  fixture: "val.meter-format fixture",
  edge: "edge cases",
  prod: "production (riskmetric scores, no val.meter metrics)"
})

md`${pkgs.length.toLocaleString("en-US")} packages loaded from the ${sourceLabels[source]}
in ${loaded.seconds.toFixed(2)} s. Data:
${Object.keys(sourceLabels).map((s) =&gt; s === source ? `**${s}**` : `[${s}](${withSource("index.html", s)})`).join(" · ")}`
















viewof matches = Inputs.search(rows, { placeholder: "Search packages…" })

Inputs.table(matches, {
  columns: ["Package", "Version", "License", ...metricCols],
  header: Object.fromEntries(metricsInfo.map((m) =&gt; [m.name, m.title])),
  format: {
    Package: (d) =&gt; htl.html`&lt;a href=${packageHref(d, source)}&gt;${d}&lt;/a&gt;`,
    ...Object.fromEntries(metricCols.map((c) =&gt; [c, formatValue]))
  },
  rows: 25,
  layout: "auto"
})
